#include <iostream>
#include <algorithm>
#include <vector>

using namespace std;

int main() {
    int n, d;
    cin >> n >> d;

    vector<int> a(n);
    for (int &x : a) cin >> x;

    sort(a.begin(), a.end());

    int maxKept = 0;
    for (int left = 0, right = 0; right < n; ++right) {
        while (a[right] - a[left] > d) {
            ++left;
        }
        maxKept = max(maxKept, right - left + 1);
    }

    cout << n - maxKept << '\n';
    return 0;
}

